"""Nov 15 2026 ML BAKE-OFF on flip quality (Rey: frame the vector as a classifier problem; pair an SVM with other ML). Declared before results. Same flips and features as report_90 (VOLX, PEERS, VR, EXT, R60, BLOW, LDV, LPX as within-month percentile ranks), TRAIN 2019-21 only (hyperparameters chosen by 3-fold time-ordered CV inside train), TEST 2022-Mar 2026 scored once. Targets: win10 (trade return >= +10%). Models: logistic (report_90 baseline), RBF SVM, gradient boosting, random forest. Metrics on TEST: AUC(win10), top-quintile-minus-bottom-quintile mean trade return (within month), month-clustered t. PASS = a nonlinear model beats the logistic by >= 0.02 AUC on TEST AND top-bottom spread. Not a claim that SVM is what the vector 'is': the vector is a rule-based pivot-ratchet state machine; here ML is used only to rank flips."""
import numpy as np, pandas as pd, warnings; warnings.filterwarnings('ignore')
from sklearn.linear_model import LogisticRegression; from sklearn.svm import SVC; from sklearn.ensemble import HistGradientBoostingClassifier, RandomForestClassifier; from sklearn.metrics import roc_auc_score; from sklearn.model_selection import TimeSeriesSplit, GridSearchCV
X = '/tmp/claude-0/-home-claude/6d3c83e1-1a4a-5a0a-8647-c2590d1d30a4/scratchpad/ext/'; F = pd.read_pickle(X + 'stack_flips.pkl').sort_values('d'); FE = ['VOLX', 'PEERS', 'VR', 'EXT', 'R60', 'BLOW', 'LDV', 'LPX']; K = ['k_' + f for f in FE]
tr = F[~F.test]; te = F[F.test].copy(); cv = TimeSeriesSplit(3)
M = {'logistic': GridSearchCV(LogisticRegression(max_iter=500), {'C': [.1, .5, 2]}, cv=cv, scoring='roc_auc'), 'rbf-svm': GridSearchCV(SVC(kernel='rbf'), {'C': [.5, 2], 'gamma': ['scale', .05]}, cv=cv, scoring='roc_auc'), 'grad-boost': GridSearchCV(HistGradientBoostingClassifier(max_depth=3, learning_rate=.05, max_iter=150), {'min_samples_leaf': [50, 200]}, cv=cv, scoring='roc_auc'), 'random-forest': GridSearchCV(RandomForestClassifier(n_estimators=200, n_jobs=-1, random_state=0), {'min_samples_leaf': [30, 100]}, cv=cv, scoring='roc_auc')}
def sc(m, d): return m.decision_function(d[K]) if hasattr(m, 'decision_function') else m.predict_proba(d[K])[:, 1]
print('test flips', len(te), 'win10 base', round(te.win10.mean(), 3))
for nm, m in M.items():
    m.fit(tr[K], tr.win10); te['sc'] = sc(m, te); a = roc_auc_score(te.win10, te.sc); at = roc_auc_score(tr.win10, sc(m, tr))
    te['q'] = te.groupby('mo').sc.transform(lambda s: pd.qcut(s.rank(method='first'), 5, labels=False) if len(s) >= 10 else np.nan); t4 = te[te.q == 4]; t0 = te[te.q == 0]; d = (t4.groupby('mo').r.mean() - t0.groupby('mo').r.mean()).dropna()
    print(f' {nm:13s} cv-auc {m.best_score_:.3f} train-auc {at:.3f} TEST AUC {a:.3f} | top-Q mean {t4.r.mean()*100:+5.1f}% (med {t4.r.median()*100:+5.1f}) bottom-Q {t0.r.mean()*100:+5.1f}% | spread {(t4.r.mean()-t0.r.mean())*100:+5.1f}pp t {d.mean()/(d.std()/np.sqrt(len(d))):+.1f} | best {m.best_params_}')
